// The parity suite runs every case in testdata/cases.json through the
// native backend against a fake Glovo API that answers from the same routes
// the upstream server was given, and compares with the upstream goldens in
// testdata/golden (generated by testdata/gen/gen.mjs from glovo-skill
// v0.2.1): the tool result, the requests sent, and the session file and
// history cache left behind.

type caseSpec struct {
	Name              string            `json:"name"`
	Tool              string            `json:"tool"`
	Args              map[string]any    `json:"args"`
	Session           json.RawMessage   `json:"session"`
	SessionText       *string           `json:"session_text"`
	Routes            []route           `json:"routes"`
	Env               map[string]string `json:"env"`
	ErrorExact        bool              `json:"error_exact"`
	UnorderedRequests bool              `json:"unordered_requests"`
	RequestsSubset    bool              `json:"requests_subset"`
	StripGoCoverage   bool              `json:"strip_go_coverage"`
}

type route struct {
	Method  string  `json:"method"`
	Path    string  `json:"path"`
	Replies []reply `json:"replies"`
}

type reply struct {
	Status  int             `json:"status"`
	File    string          `json:"file"`
	JSON    json.RawMessage `json:"json"`
	Text    *string         `json:"text"`
	Network bool            `json:"network"`
}

type spec struct {
	NowMS    int64                      `json:"now_ms"`
	Sessions map[string]json.RawMessage `json:"sessions"`
	Cases    []caseSpec                 `json:"cases"`
}

type golden struct {
	Result            *mcp.CallToolResult `json:"-"`
	RawResult         json.RawMessage     `json:"result"`
	Requests          []recorded          `json:"requests"`
	SessionAfter      fileState           `json:"session_after"`
	HistoryCacheAfter fileState           `json:"history_cache_after"`
}

type recorded struct {
	Method string `json:"method"`
	URI    string `json:"uri"`
	Body   any    `json:"body"`
}

type fileState struct {
	Exists bool   `json:"exists"`
	Mode   string `json:"mode,omitempty"`
	JSON   any    `json:"json,omitempty"`
	Text   string `json:"text,omitempty"`
}

func loadSpec(t *testing.T) *spec {
	t.Helper()
	b, err := os.ReadFile("testdata/cases.json")
	if err != nil {
		t.Fatal(err)
	}
	var s spec
	if err := json.Unmarshal(b, &s); err != nil {
		t.Fatal(err)
	}
	return &s
}

func loadGolden(t *testing.T, name string) *golden {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", "golden", name+".json")) // #nosec G304 -- test golden named by cases.json
	if err != nil {
		t.Fatal(err)
	}
	var g golden
	if err := json.Unmarshal(b, &g); err != nil {
		t.Fatal(err)
	}
	var r struct {
		Content []struct {
			Type string `json:"type"`
			Text string `json:"text"`
		} `json:"content"`
		IsError bool `json:"isError"`
	}
	if err := json.Unmarshal(g.RawResult, &r); err != nil {
		t.Fatal(err)
	}
	g.Result = &mcp.CallToolResult{IsError: r.IsError}
	for _, c := range r.Content {
		g.Result.Content = append(g.Result.Content, mcp.TextContent{Type: c.Type, Text: c.Text})
	}
	return &g
}

// fakeGlovo answers like stub.mjs: per method and path, replies in order,
// the last one repeating; an unrouted request is a 500.
type fakeGlovo struct {
	t      *testing.T
	routes []route
	mu     sync.Mutex
	served map[string]int
	log    []recorded
}

func (f *fakeGlovo) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	body, _ := io.ReadAll(r.Body)
	var parsed any
	if len(body) > 0 {
		if err := json.Unmarshal(body, &parsed); err != nil {
			parsed = string(body)
		}
	}
	f.mu.Lock()
	f.log = append(f.log, recorded{Method: r.Method, URI: r.URL.RequestURI(), Body: parsed})
	var rt *route
	for i := range f.routes {
		if f.routes[i].Method == r.Method && f.routes[i].Path == r.URL.Path {
			rt = &f.routes[i]
			break
		}
	}
	if rt == nil {
		f.mu.Unlock()
		w.WriteHeader(http.StatusInternalServerError)
		_, _ = io.WriteString(w, `{"error":{"exceptionName":"unrouted"}}`)
		return
	}
	key := r.Method + " " + r.URL.Path
	n := f.served[key]
	f.served[key] = n + 1
	f.mu.Unlock()
	rep := rt.Replies[min(n, len(rt.Replies)-1)]
	if rep.Network {
		hj, ok := w.(http.Hijacker)
		if !ok {
			f.t.Error("cannot simulate a network failure")
			return
		}
		conn, _, err := hj.Hijack()
		if err == nil {
			_ = conn.Close()
		}
		return
	}
	var out []byte
	switch {
	case rep.File != "":
		b, err := os.ReadFile(filepath.Join("testdata", rep.File))
		if err != nil {
			f.t.Error(err)
		}
		out = b
	case rep.JSON != nil:
		out = rep.JSON
	case rep.Text != nil:
		out = []byte(*rep.Text)
	default:
		out = []byte("{}")
	}
	status := rep.Status
	if status == 0 {
		status = http.StatusOK
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(out)
}

func (f *fakeGlovo) requests() []recorded {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]recorded(nil), f.log...)
}

func noSleep(context.Context, time.Duration) error { return nil }

type harness struct {
	backend *Backend
	fake    *fakeGlovo
	dir     string
	session string
}

func newHarness(t *testing.T, s *spec, c caseSpec) *harness {
	t.Helper()
	dir := filepath.Join(t.TempDir(), "glovo")
	if err := os.Mkdir(dir, 0o700); err != nil {
		t.Fatal(err)
	}
	sessionPath := filepath.Join(dir, "session.json")
	var session json.RawMessage
	var name string
	if json.Unmarshal(c.Session, &name) == nil {
		session = s.Sessions[name]
	} else if string(c.Session) != "null" && len(c.Session) > 0 {
		session = c.Session
	}
	switch {
	case c.SessionText != nil:
		writeFile(t, sessionPath, []byte(*c.SessionText))
	case session != nil:
		var buf bytes.Buffer
		if err := json.Indent(&buf, session, "", "  "); err != nil {
			t.Fatal(err)
		}
		writeFile(t, sessionPath, buf.Bytes())
	}
	fake := &fakeGlovo{t: t, routes: c.Routes, served: map[string]int{}}
	srv := httptest.NewServer(fake)
	t.Cleanup(srv.Close)
	now := time.UnixMilli(s.NowMS)
	clock := func() time.Time { return now }
	var ids int
	var idMu sync.Mutex
	newID := func() string {
		idMu.Lock()
		defer idMu.Unlock()
		ids++
		return fmt.Sprintf("00000000-0000-4000-8000-%012d", ids)
	}
	b, err := New(Config{
		SessionPath: sessionPath,
		ClientOptions: []glovoapi.Option{
			glovoapi.WithBaseURL(srv.URL), glovoapi.WithHTTPClient(srv.Client()),
			glovoapi.WithClock(clock), glovoapi.WithIDGenerator(newID), glovoapi.WithSleep(noSleep),
			glovoapi.WithDefaultLocation(glovoapi.DefaultLocationFromEnv(func(k string) string { return c.Env[k] })),
		},
		GoogleAPIKey: c.Env["GOOGLE_MAPS_API_KEY"],
		Now:          clock,
		Sleep:        noSleep,
	})
	if err != nil {
		t.Fatal(err)
	}
	return &harness{backend: b, fake: fake, dir: dir, session: sessionPath}
}

func writeFile(t *testing.T, path string, b []byte) {
	t.Helper()
	if err := os.WriteFile(path, b, 0o600); err != nil {
		t.Fatal(err)
	}
}

func readState(t *testing.T, path string) fileState {
	t.Helper()
	b, err := os.ReadFile(path) // #nosec G304 -- a file in the test temp dir
	if os.IsNotExist(err) {
		return fileState{}
	}
	if err != nil {
		t.Fatal(err)
	}
	info, err := os.Stat(path)
	if err != nil {
		t.Fatal(err)
	}
	st := fileState{Exists: true, Mode: fmt.Sprintf("%o", info.Mode().Perm())}
	var v any
	if json.Unmarshal(b, &v) == nil {
		st.JSON = v
	} else {
		st.Text = string(b)
	}
	return st
}

var reUUID = regexp.MustCompile(`[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}`)

func normalizeRequests(rs []recorded) []string {
	out := make([]string, len(rs))
	for i, r := range rs {
		b, _ := json.Marshal(r.Body)
		out[i] = reUUID.ReplaceAllString(r.Method+" "+r.URI+" "+string(b), "<uuid>")
	}
	return out
}

func resultText(r *mcp.CallToolResult) string {
	if r == nil || len(r.Content) != 1 {
		return fmt.Sprintf("<%d content items>", len(r.Content))
	}
	tc, ok := r.Content[0].(mcp.TextContent)
	if !ok {
		return "<non-text content>"
	}
	return tc.Text
}

func canonical(t *testing.T, text string, stripCoverage bool) any {
	t.Helper()
	var v any
	if err := json.Unmarshal([]byte(text), &v); err != nil {
		t.Fatalf("result is not JSON: %v\n%s", err, text)
	}
	if stripCoverage {
		if cov, ok := v.(map[string]any)["coverage"].(map[string]any); ok {
			delete(cov, "store_content_failures")
			delete(cov, "product_lookup_failures")
		}
	}
	return v
}

func pretty(v any) string {
	b, _ := json.MarshalIndent(v, "", "  ")
	return string(b)
}

func TestParityWithUpstream(t *testing.T) {
	s := loadSpec(t)
	for _, c := range s.Cases {
		t.Run(c.Name, func(t *testing.T) {
			want := loadGolden(t, c.Name)
			h := newHarness(t, s, c)
			got, err := h.backend.Call(context.Background(), c.Tool, c.Args)
			if err != nil {
				t.Fatalf("Call: %v", err)
			}
			checkResult(t, c, got, want.Result)
			checkRequests(t, c, normalizeRequests(h.fake.requests()), normalizeRequests(want.Requests))
			if sa := readState(t, h.session); !reflect.DeepEqual(sa, want.SessionAfter) {
				t.Errorf("session after:\n got %s\nwant %s", pretty(sa), pretty(want.SessionAfter))
			}
			if hc := readState(t, filepath.Join(h.dir, "history-cache.json")); !reflect.DeepEqual(hc, want.HistoryCacheAfter) {
				t.Errorf("history cache after:\n got %s\nwant %s", pretty(hc), pretty(want.HistoryCacheAfter))
			}
		})
	}
}

func checkResult(t *testing.T, c caseSpec, got, want *mcp.CallToolResult) {
	t.Helper()
	gotText, wantText := resultText(got), resultText(want)
	if got.IsError != want.IsError {
		t.Fatalf("isError = %v, want %v\n got %s\nwant %s", got.IsError, want.IsError, gotText, wantText)
	}
	switch {
	case want.IsError:
		// Every error text is compared exactly, error_exact or not: the
		// upstream messages are part of the tool surface.
		if gotText != wantText {
			t.Errorf("error text:\n got %q\nwant %q", gotText, wantText)
		}
	case c.Tool == "glovo_get_shopping_guide":
		if gotText != wantText {
			t.Errorf("shopping guide differs")
		}
	default:
		g, w := canonical(t, gotText, c.StripGoCoverage), canonical(t, wantText, c.StripGoCoverage)
		if !reflect.DeepEqual(g, w) {
			t.Errorf("result:\n got %s\nwant %s", pretty(g), pretty(w))
		}
	}
}

func checkRequests(t *testing.T, c caseSpec, got, want []string) {
	t.Helper()
	if c.UnorderedRequests {
		got, want = sorted(got), sorted(want)
	}
	if c.RequestsSubset {
		// Upstream issues these reads in parallel and sends all of them;
		// Go reads in order and stops at the first failure.
		left := map[string]int{}
		for _, w := range want {
			left[w]++
		}
		for _, g := range got {
			if left[g] == 0 {
				t.Errorf("request %s was not sent upstream", g)
			}
			left[g]--
		}
		return
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("requests:\n got %s\nwant %s", strings.Join(got, "\n     "), strings.Join(want, "\n     "))
	}
}

func sorted(s []string) []string {
	out := append([]string(nil), s...)
	sort.Strings(out)
	return out
}
